import { Resvg } from "@cf-wasm/resvg";

class ImageCombiner {
  public combine(
    width: number,
    height: number,
    bytes: Uint8Array[],
    textOptions?: {
      x: number;
      y: number;
      text: string;
      fontSize: number;
      color: string;
    },
  ): Uint8Array<ArrayBufferLike> {
    let svgs: string[] = [
      `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">`,
    ];
    bytes.forEach((bytes) => {
      svgs.push('<image href="data:image/png;base64,');
      svgs.push(btoa(String.fromCharCode(...bytes)));
      svgs.push(`" x="0" y="0" width="${width}" height="${height}" />`);
    });

    if (textOptions) {
      const { x, y, text } = textOptions;
      svgs.push(
        '<style>@font-face {font-family: "customFont";src: url(\'data:font/woff2;base64,\') format("woff2");}',
      );
      svgs.push(
        `text { font-family:"customFont"; font-size:${textOptions.fontSize}px; fill:${textOptions.color}; }</style>`,
      );
      svgs.push(
        `<text x="${x}" y="${y}" dominant-baseline="central" text-anchor="middle">${
          text.replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;")
            .replace(/[\x00-\x1F\x7F]/g, "")
            .trim()
        }</text>`,
      );
    }

    svgs.push("</svg>");
    const resvg = new Resvg(
      svgs.join(""),
      !textOptions ? { fitTo: { mode: "width", value: width } } : {
        fitTo: { mode: "width", value: width },
        font: {
          defaultFontFamily: "customFont",
          loadSystemFonts: false,
        },
      },
    );
    return resvg.render().asPng();
  }
}

export default new ImageCombiner();
